/**
 * Synthesizes the app's royalty-free sound effects from scratch (pure sine/tri
 * tones — generated by this script, CC0, no third-party samples).
 * Output: public/audio/sfx/*.wav + LICENSES.md
 *
 * Run: node scripts/gen-sfx.mjs
 */
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const SR = 44100;
const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const out = join(root, 'public', 'audio', 'sfx');
mkdirSync(out, { recursive: true });

function buffer(durationSec) {
  return new Float32Array(Math.ceil(durationSec * SR));
}

/** add a tone: freq can be a number or fn(t01)->Hz */
function tone(buf, { f, start = 0, dur, vol = 0.5, type = 'sine', attack = 0.01, release = 0.08 }) {
  const n0 = Math.floor(start * SR);
  const n1 = Math.min(buf.length, n0 + Math.floor(dur * SR));
  let phase = 0;
  for (let i = n0; i < n1; i++) {
    const t = (i - n0) / SR;
    const t01 = t / dur;
    const freq = typeof f === 'function' ? f(t01) : f;
    phase += (2 * Math.PI * freq) / SR;
    let v = Math.sin(phase);
    if (type === 'tri') v = (2 / Math.PI) * Math.asin(v);
    let env = 1;
    if (t < attack) env = t / attack;
    const tail = dur - t;
    if (tail < release) env = Math.min(env, tail / release);
    buf[i] += v * vol * env;
  }
}

function writeWav(name, buf) {
  const n = buf.length;
  const data = Buffer.alloc(44 + n * 2);
  data.write('RIFF', 0);
  data.writeUInt32LE(36 + n * 2, 4);
  data.write('WAVE', 8);
  data.write('fmt ', 12);
  data.writeUInt32LE(16, 16);
  data.writeUInt16LE(1, 20);
  data.writeUInt16LE(1, 22);
  data.writeUInt32LE(SR, 24);
  data.writeUInt32LE(SR * 2, 28);
  data.writeUInt16LE(2, 32);
  data.writeUInt16LE(16, 34);
  data.write('data', 36);
  data.writeUInt32LE(n * 2, 40);
  for (let i = 0; i < n; i++) {
    const v = Math.max(-1, Math.min(1, buf[i]));
    data.writeInt16LE(Math.round(v * 32767), 44 + i * 2);
  }
  writeFileSync(join(out, name), data);
  console.log('  •', name, (data.length / 1024).toFixed(1) + ' KB');
}

// click — tiny tick
{
  const b = buffer(0.07);
  tone(b, { f: 1250, dur: 0.05, vol: 0.32, type: 'tri', attack: 0.002, release: 0.04 });
  writeWav('click.wav', b);
}
// pop — selection pop (rising chirp)
{
  const b = buffer(0.12);
  tone(b, { f: (t) => 480 + 520 * t, dur: 0.1, vol: 0.4, attack: 0.004, release: 0.05 });
  writeWav('pop.wav', b);
}
// correct — happy major arpeggio + sparkle
{
  const b = buffer(0.55);
  tone(b, { f: 523.25, start: 0.0, dur: 0.16, vol: 0.34 });
  tone(b, { f: 659.25, start: 0.1, dur: 0.16, vol: 0.34 });
  tone(b, { f: 783.99, start: 0.2, dur: 0.22, vol: 0.36 });
  tone(b, { f: 1567.98, start: 0.3, dur: 0.18, vol: 0.16 });
  writeWav('correct.wav', b);
}
// wrong — gentle soft "uh-oh", no harshness
{
  const b = buffer(0.4);
  tone(b, { f: (t) => 300 - 60 * t, dur: 0.16, vol: 0.22, attack: 0.01, release: 0.08 });
  tone(b, { f: (t) => 240 - 50 * t, start: 0.18, dur: 0.2, vol: 0.2, attack: 0.01, release: 0.1 });
  writeWav('wrong.wav', b);
}
// win — celebration fanfare
{
  const b = buffer(1.3);
  const seq = [
    [523.25, 0.0],
    [659.25, 0.12],
    [783.99, 0.24],
    [1046.5, 0.36]
  ];
  for (const [f, s] of seq) tone(b, { f, start: s, dur: 0.18, vol: 0.3 });
  // closing chord
  for (const f of [523.25, 659.25, 783.99, 1046.5]) tone(b, { f, start: 0.56, dur: 0.6, vol: 0.18, release: 0.35 });
  tone(b, { f: 2093, start: 0.7, dur: 0.3, vol: 0.1 });
  writeWav('win.wav', b);
}

writeFileSync(
  join(root, 'public', 'audio', 'LICENSES.md'),
  `# Audio asset licenses

All sound effects in \`/public/audio/sfx/\` (click.wav, pop.wav, correct.wav,
wrong.wav, win.wav) were **synthesized from scratch** by \`scripts/gen-sfx.mjs\`
in this repository (pure generated sine/triangle tones, no third-party samples).

License: **CC0 / public domain** — free to use, no attribution required.

TTS clips under \`/public/audio/tts/\` are generated at seed time from the
project's own lesson text via the Google Gemini TTS API (see scripts/seed-tts.mjs).
`
);
console.log('✅ SFX generated + LICENSES.md written');
